import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

# Function to calculate f(K_n) - number of triangles (K3)
def f_kn(n):
    return combinations(n, 3)

# Function to calculate g(K_n) - number of tetrahedra (K4)
def g_kn(n):
    return combinations(n, 4)

ratios = {}
for n in range(3, 7):
    f = f_kn(n)
    g = g_kn(n)

    # Calculate the ratio g^3 / f^4
    # Since we are dealing with integers, we should keep the calculation precise.
    if f == 0:
        ratio = float('inf') if g > 0 else 0
    else:
        ratio = (g**3) / (f**4)

    ratios[n] = {
        'f': f,
        'g': g,
        'ratio': ratio
    }

print("Calculations for K_3 to K_6:")
for n, data in ratios.items():
    print(f"--- K_{n} ---")
    print(f"f(K_{n}) (Triangles): {data['f']}")
    print(f"g(K_{n}) (Tetrahedra): {data['g']}")
    print(f"Ratio g^3 / f^4: {data['ratio']}")
